		b, err := json.Marshal(struct {
			Name      string `json:"name"`
			Authority string `json:"authority"`
			Profile   string `json:"profile"`
		}{
			Name:      cur.Name,
			Authority: cur.Authority,
			Profile:   cur.Profile,
